// src/server.js
var PANEL_URI = "ui://forge/panel.html";
var MAP_URI = "ui://forge/map.html";
var VERSION = "0.1.0";
var readChatSetting = () => /^(1|true|yes|on)$/i.test(String(process.env.FORGE_READ_CHAT || "").trim());
var INSTRUCTIONS = [
  "Forge writes expert prompts for other AIs (image, video, voice, music, chat, coding, app builders, research). Forge is the expert; you (Claude) are the writer.",
  "The flow: forge_pick_ai (which AI fits the job) -> forge_questions (at most 3 short questions; ask the person, skip any they don't care about) -> forge_brief (Forge's full brief) -> you write the final prompt from the brief -> forge_check (fix every problem it lists, then show the person the prompt). Never show a prompt that has not passed forge_check: after any fix (yours or fixed_prompt), call forge_check again. Up to 3 tries; if it still fails, show it and say plainly which problems are left.",
  "If the person already named the AI, skip forge_pick_ai. Never ask a question the person already answered.",
  // Oct 2026 (Alon: "not a website in Claude, actually in Claude"): everything happens in the chat itself
  "Keep Forge inside the chat. Ask Forge's questions with your own question tool when you have one (in Claude Code: AskUserQuestion, all questions in one call, each question's options as choices; for a question without options, offer 2 or 3 likely answers yourself; the person can always type their own). Otherwise ask them in one short message. Show the result as a code block in the chat. Do not open the Forge panel (forge_open) unless the person asks for the panel or a form by name.",
  "Reverse Forge (a picture the person wants more of): if you can see it, YOU describe it precisely, call forge_reverse with that description (and image_path for a PNG file in Claude Code), write the prompt from its rules, then forge_check with request = your description.",
  '"Read this chat" is OFF by default. Only when the person turns it on (they say so in this chat, or the Read this chat setting is on) may you send the conversation to forge_chat_context. Otherwise use only the request they give you.',
  "After forge_check passes, always show the prompt in a code block so the person can copy it. Then offer, in one line, to use it now: if the prompt is for you (Claude, or any chat or coding job you can do here), you may run it yourself once they say yes; if a tool for the target AI is connected in this session (for example an image or video generator), offer to send it there and do so only after they say yes, because other AIs can cost credits. Otherwise, copying is the way.",
  "Forge keeps no data: nothing you send is saved, logged or sent anywhere."
].join("\n");
var AI = external_exports.string().min(1).describe('The AI to write for: a Forge id such as "nanobanana", "midjourney", "claudecode", or its name. forge_pick_ai returns ids.');
var REQUEST = external_exports.string().min(1).describe("What the person wants, in their own words. Pass it unchanged (typos are fine, Forge fixes spelling).");
var ANSWERS = external_exports.record(external_exports.string(), external_exports.string()).optional().describe(`The person's answers to forge_questions, keyed by the question's field (e.g. {"light": "neon at night"}). Leave out skipped questions.`);
var RO = { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false };
var reply = (text, data) => ({ content: [{ type: (
  /** @type {const} */
  "text"
), text }], structuredContent: data });
var nameOf = (ai) => {
  const m2 = findModel(ai);
  return m2 ? m2.n + (m2.sub ? " " + m2.sub : "") : ai;
};
function createServer() {
  const server = new McpServer({ name: "forge", version: VERSION }, { instructions: INSTRUCTIONS });
  server.registerTool("forge_pick_ai", {
    title: "Pick the AI",
    description: "Find the best AIs for a job, best first, each with a one-line reason in the person's terms. Use when the person has not said which AI they will use. Returns Forge ids to pass to the other tools.",
    inputSchema: {
      request: REQUEST,
      kind: external_exports.enum(
        /** @type {[string, ...string[]]} */
        engine_default.JOB_KINDS
      ).optional().describe("What kind of thing they want. Pass it whenever you can tell (you usually can): it makes the pick much better. image, video, voice (spoken words), sfx (sound effect), music, text (writing or advice), code (changing code), app (build an app without coding), research."),
      count: external_exports.number().int().min(1).max(5).optional().describe("How many picks to return (default 3).")
    },
    annotations: RO
  }, async (a) => {
    const r2 = pickAI(a);
    return reply(pickText(r2), r2);
  });
  server.registerTool("forge_questions", {
    title: "Questions worth asking",
    description: "The at most 3 short questions that would change the result most for this AI, best first. Never repeats what the request or earlier answers already say. Ask the person all of them at once; they may skip any. Empty list means go straight to forge_brief.",
    inputSchema: { request: REQUEST, ai: AI, answers: ANSWERS },
    annotations: RO
  }, async (a) => {
    const r2 = questions(a);
    return reply(questionsText(r2), r2);
  });
  server.registerTool("forge_brief", {
    title: "Get Forge's brief",
    description: "Forge's full expert brief for writing this prompt: what the person said, Forge's draft and settings, how this AI wants prompts, facts and expert tips, and the rules. You are the writer: write the final prompt from this brief, then call forge_check. Follow the brief's RULES and its REPLY WITH shape. Do not show the brief to the person unless they ask.",
    inputSchema: { request: REQUEST, ai: AI, answers: ANSWERS },
    annotations: RO
  }, async (a) => {
    const m2 = needModel(a.ai), r2 = { ai: m2.id, name: nameOf(m2.id), brief: brief(a) };
    return reply(briefText(r2), r2);
  });
  server.registerTool("forge_check", {
    title: "Check the prompt you wrote",
    description: "Check the prompt you wrote from forge_brief. Answers: kept every fact the person gave? settings real for this AI? anything invented? Returns {ok, checks, problems, fixed_prompt?}. If problems are listed, fix them (or use fixed_prompt) before showing the person. Pass the same request and answers you gave forge_brief.",
    inputSchema: {
      request: REQUEST,
      ai: AI,
      answers: ANSWERS,
      prompt: external_exports.string().min(1).describe(`The prompt you wrote. You may include the "Prompt: / Negative: / Settings:" lines from the brief's REPLY WITH shape.`)
    },
    annotations: RO
  }, async (a) => {
    const r2 = { ...check2(a), name: nameOf(a.ai) };
    return reply(checkText(r2), r2);
  });
  server.registerTool("forge_chat_context", {
    title: "Read this chat (off by default)",
    description: 'Turn this conversation into context for another AI: what was asked, what was decided, the facts that matter. "Read this chat" is OFF by default: call this ONLY if the person turned it on (they asked you to, or the setting is on), and set user_turned_on to true only if they did. Never call it on your own.',
    inputSchema: {
      conversation: external_exports.string().min(1).describe("The conversation so far, as plain text (who said what)."),
      user_turned_on: external_exports.boolean().optional().describe("true only if the person asked, in this chat, for Forge to read the chat.")
    },
    annotations: RO
  }, async (a) => {
    const r2 = !readChatSetting() && a.user_turned_on !== true ? { available: false, message: "Read this chat is off. Ask the person if Forge may read this chat; only if they say yes, call again with user_turned_on: true." } : chatContext2(a);
    return reply(chatText(r2), r2);
  });
  K3(server, "forge_map", {
    title: "Forge Map",
    description: "Forge Map: a map of the person's own chat or project text: its main topics, how they group, and what is still missing. Use it when the person asks for a map or overview of their context. Hosts that show apps draw the map inside the chat; otherwise show the text answer as it is. Never put the map in a file, an artifact, a web page or a new tab. Pass only text the person gave you or asked you to map; nothing is kept.",
    inputSchema: { text: external_exports.string().min(1).describe("The chat or project text to map (what the person pasted, or this conversation if they asked).") },
    annotations: RO,
    _meta: { ui: { resourceUri: MAP_URI } }
  }, async (a) => {
    const r2 = map2(a);
    return reply(mapText(r2), r2);
  });
  server.registerTool("forge_reverse", {
    title: "Reverse Forge",
    description: "Work backwards from a picture the person already has to a prompt that makes more like it, for the AI they pick. If you can see the picture, YOU are the eyes: describe it precisely (subject, action, setting, camera, light, colours, style, any text word for word) and pass that as description. Forge answers with that AI's rules and settings (aspect from the measures); you then write the prompt and call forge_check with request = your description. In Claude Code, pass image_path when the person gave a file: Forge measures PNG files read-only. Without a description, Forge returns a message to send with the picture to a vision AI.",
    inputSchema: {
      ai: AI,
      description: external_exports.string().optional().describe("What YOU see in the picture, precisely: subject, action, setting, camera, light, colours, style, any text word for word. Required whenever you can see the picture."),
      measures: external_exports.record(external_exports.string(), external_exports.unknown()).optional().describe('Measurements if you have them, e.g. from the Forge website: {"w": 1920, "h": 1080, "ratio": "16:9", "top": ["#1a2b3c"]}. width/height also work.'),
      notes: external_exports.string().optional().describe('What the person wants to keep or change (e.g. "same scene but at night").'),
      image_path: external_exports.string().optional().describe("Claude Code only: the picture's file path, if the person gave one. Forge reads it (never writes) and measures it. PNG only; for JPEG or WebP, skip it (or measure on the Forge website).")
    },
    annotations: RO
  }, async (a) => {
    const r2 = reverse(a);
    return reply(reverseText(r2, nameOf(a.ai)), r2);
  });
  K3(server, "forge_open", {
    title: "Open the Forge panel",
    description: "Open the Forge panel: a small form where the person picks the AI, types what they want, answers Forge's few questions, and presses Write it (you then get a message asking you to write the prompt from Forge's brief) or Copy brief. Use it ONLY when the person asks for the Forge panel or a form by name; for everything else run the normal flow right in the chat. Pass the request and AI if you already know them. Hosts without panels (Claude Code) only get the text: then run the normal flow.",
    inputSchema: {
      request: external_exports.string().optional().describe("What the person wants, if they already said it."),
      ai: external_exports.string().optional().describe("The Forge id of the AI, if already known (forge_pick_ai returns ids).")
    },
    annotations: RO,
    _meta: { ui: { resourceUri: PANEL_URI } }
  }, async (a) => {
    const m2 = a.ai ? findModel(a.ai) : void 0;
    const r2 = { models: models(), ...a.request ? { request: a.request } : {}, ...m2 ? { ai: m2.id } : {} };
    return reply(openText(r2), r2);
  });
  N3(server, "Forge panel", PANEL_URI, {
    description: "The Forge panel: pick the AI, the request, up to 3 questions, Write it and Copy brief. Self-contained, no network, keeps nothing."
  }, async () => ({
    contents: [{ uri: PANEL_URI, mimeType: p, text: panel_html_default, _meta: { ui: { prefersBorder: true } } }]
  }));
  N3(server, "Forge Map", MAP_URI, {
    description: "The Forge Map: the person's chat as a map (goal, decisions, rules, open questions, latest ask, main topics), shown inside the chat. Self-contained, no network, keeps nothing."
  }, async () => ({
    contents: [{ uri: MAP_URI, mimeType: p, text: map_html_default, _meta: { ui: { prefersBorder: true } } }]
  }));
  return server;
}
async function main() {
  const server = createServer();
  await server.connect(new StdioServerTransport());
}

// src/main.js
main().catch((e) => {
  process.stderr.write("Forge MCP could not start: " + (e && e.message || e) + "\n");
  process.exit(1);
});
